/// <summary>
/// create String
/// </summary>
public Notes getConditions(METFulfilmentProfileId _profileId)
{
    Notes queryString;
    container packedQuery = METFulfilmentProfile::find(_profileId).ConditionQueryPacked;

    Query conditon;
    int dsN;
    int dsI;

    void addFilter(Query _query)
    {
        int nFilter = _query.queryFilterCount();
        int iFilter;

        for (iFilter = 1; iFilter <= nFilter; iFilter++)
        {
            QueryFilter qf = _query.queryFilter(iFilter);

            if (qf.value() && qf.status() != RangeStatus::Hidden)
            {
                QueryBuildDataSource qbds = qf.dataSource();
                TableId tableId = qbds.table();
                FieldId fieldId = fieldName2Id(tableId, qf.field());

                queryString += strFmt("%1; %2; %3|", tableId, fieldId, qf.value());
            }
        }
    }

    void addRange(QueryBuildRange _range)
    {
        if (_range.value() && _range.status() != RangeStatus::Hidden)
        {
            queryString += strFmt("%1; %2; %3|", _range.table(), _range.field(), _range.value());
        }
    }

    void addDatasource(QueryBuildDataSource _ds)
    {
        int nRange = _ds.rangeCount();
        int iRange;
        for (iRange = 1; iRange <= nRange; iRange++)
        {
            addRange(_ds.range(iRange));
        }
    }


    if (conlen(packedQuery) > 0)
    {
        conditon = new Query(packedQuery);
        dsN = conditon.dataSourceCount();
        for (dsI = 1; dsI <= dsN; dsI++)
        {
            addDatasource(conditon.dataSourceNo(dsI));
        }

        addFilter(conditon);
    }

    return queryString;
}

/// <summary>
/// Post load method to convert the query conditions 
/// </summary>
public void postLoad()
{
    super();
    METFulfilmentProfile fulfilmentProfile = METFulfilmentProfile::find(this.ProfileId);

    if (fulfilmentProfile.RecId)
    {
        this.Conditions = this.getConditions(this.ProfileId);
    }
}

/// <summary>
///
/// </summary>
/// <param name = "_entityCtx"></param>
/// <param name = "_dataSourceCtx"></param>
public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(METFulfilmentProfileEntity, METFulfilmentProfile) && this.Conditions)
    {
        METFulfilmentProfile fulfilmentProfile = _dataSourceCtx.getBuffer() as METFulfilmentProfile;

        List conditionsList = strSplit(this.Conditions, '|');

        ListEnumerator conditionsEnum = conditionsList.getEnumerator();
        Query query = METFulfilmentProfile::defaultQuery();
        while (conditionsEnum.moveNext())
        {
            str condition = conditionsEnum.current();
            List conditionParts = strSplit(condition, ';');

            TableId tableId;
            FieldId fieldId;
            str value;

            Counter partCounter = 1;    
            ListEnumerator conditionPartsEnum = conditionParts.getEnumerator();

            while (conditionPartsEnum.moveNext())
            {
                if (partCounter == 1)
                {
                    tableId = str2Int(conditionPartsEnum.current());
                }
                else if (partCounter == 2)
                {
                    fieldId = str2Int(conditionPartsEnum.current());
                }
                else if (partCounter == 3)
                {
                    value = conditionPartsEnum.current();
                    QueryBuildDataSource qbds = query.dataSourceTable(tableId);
                    if (qbds)
                    {
                        QueryBuildRange qbr = qbds.addRange(fieldId);
                        qbr.value(value);
                    }
                }
                partCounter++;
            }
        }

        fulfilmentProfile.ConditionQueryPacked = query.pack();
    }

    super(_entityCtx, _dataSourceCtx);
}
